import java.util.ArrayList;
import java.util.List;

public class TimeRangeBuilder {
    private static final long FETCH_DATA_DURATION = 10000; // Example duration in milliseconds

    /**
     * Split time ranges to insure the start time and end time is small then  {@link #FETCH_DATA_DURATION}
     *
     * @param start The start time of the range
     * @param end   The end time of the range
     * @return A list of time ranges
     */
    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        if (start >= end) {
            throw new IllegalArgumentException("Start time must be less than end time");
        }

        long duration = end - start;
        if (duration >= FETCH_DATA_DURATION) {
            long rangeSize = FETCH_DATA_DURATION / 2;
            long rangeStart = start;
            long rangeEnd = start + rangeSize;

            while (rangeEnd <= end) {
                timeRanges.add(new TimeRange(rangeStart, rangeEnd));
                rangeStart += rangeSize;
                rangeEnd += rangeSize;
            }
        } else {
            timeRanges.add(new TimeRange(start, end));
        }

        return timeRanges;
    }
}

class TimeRange {
    private long start;
    private long end;

    public TimeRange(long start, long end) {
        this.start = start;
        this.end = end;
    }

    public long getStart() {
        return start;
