public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Time bucket and day step must be positive integers.");
    }

    long startYear = timeBucket / (1000 * 60 * 60 * 24 * 365);
    long startMonth = (timeBucket % (1000 * 60 * 60 * 24 * 365)) / (1000 * 60 * 60 * 24 * 30);
    long startDay = (timeBucket % (1000 * 60 * 60 * 24 * 30)) % (1000 * 60 * 60 * 24);

    long compressedTimeBucket = startYear * (1000 * 60 * 60 * 24 * 365) + startMonth * (1000 * 60 * 60 * 24 * 30) + startDay;

    if (dayStep > 1) {
        compressedTimeBucket += (dayStep - 1) * (1000 * 60 * 60 * 24);
    }

    return compressedTimeBucket;
}
