import java.net.URI;
import java.util.ArrayList;
import java.util.List;

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }

    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }

    List<PathSegmentImpl> segments = new ArrayList<>();
    StringBuilder segment = new StringBuilder();
    boolean isAbsolute = u.isAbsolute();

    for (int i = 0; i < path.length(); i++) {
        char c = path.charAt(i);

        if (c == '/') {
            if (segment.length() > 0) {
                if (decode) {
                    segment = new StringBuilder(decodeURIComponent(segment.toString()));
                }
                segments.add(new PathSegmentImpl(segment.toString(), isAbsolute));
                segment = new StringBuilder();
            }
            isAbsolute = true;
        } else {
            segment.append(c);
        }
    }

    if (segment.length() > 0) {
        if (decode) {
            segment = new StringBuilder(decodeURIComponent(segment.toString()));
        }
        segments.add(new PathSegmentImpl(segment.toString(), isAbsolute));
    }

    return segments;
}

private static String decodeURIComponent(String s) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '%') {
            if (i + 2 < s.length()) {
                char hex1 = s.charAt(i + 1);
                char hex2 = s.charAt(i + 2);
                if (Character.isDigit(hex1) && Character.isDigit(hex2)) {
                    int decoded = Integer.parseInt(String.valueOf(hex1) + String.valueOf(hex2), 16);
                    result.append((char) decoded);
                    i += 2;
                }
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}
