public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < len) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 'n':
                        result.append('\n');
                        i++; // Skip the next character
                        break;
                    case 't':
                        result.append('\t');
                        i++; // Skip the next character
                        break;
                    case 'r':
                        result.append('\r');
                        i++; // Skip the next character
                        break;
                    case 'b':
                        result.append('\b');
                        i++; // Skip the next character
                        break;
                    case 'f':
                        result.append('\f');
                        i++; // Skip the next character
                        break;
                    case 'u':
                        if (i + 4 < len) {
                            int code = Integer.parseInt(str.substring(i + 2, i + 6), 16);
                            result.append((char) code);
                            i += 5; // Skip the next 5 characters
                        } else {
                            throw new IllegalArgumentException("Invalid Unicode escape sequence");
                        }
                        break;
                    default:
                        result.append(c);
                        break;
                }
            } else {
                throw new IllegalArgumentException("Invalid escape sequence");
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}
