private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null || dir < 0) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Node current = start;
    while (current != stop) {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
        current = getNextNode(current, dir);
    }

    return new OuterFaceCirculator(stop);
}

private Node getNextNode(Node current, int dir) {
    switch (dir) {
        case 0: // North
            return current.getNorth();
        case 1: // East
            return current.getEast();
        case 2: // South
            return current.getSouth();
        case 3: // West
            return current.getWest();
        default:
            throw new IllegalArgumentException("Invalid direction");
    }
}
