        throw new IllegalArgumentException("Buckets and labels cannot be null or empty");
    }

    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid minLabel value");
    }

    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    if (minLabelBucket != null) {
        bucketsByLabel.get(0).addAll(minLabelBucket);
        minLabelBucket.clear();
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.set(minLabel, new HashSet<>());

    // Update the labeling accordingly
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            labels.set(i, 0);
        }
    }
}
