import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse the line to create a ThreadSnapshot object
            ThreadSnapshot snapshot = parseLine(line);
            // Check if the snapshot is within the specified time range
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timeRange.isInRange(snapshot.getTime())) {
                    threadSnapshots.add(snapshot);
                    break;
                }
            }
        }
    }
    return threadSnapshots;
}

private static ThreadSnapshot parseLine(String line) {
    // Implement the logic to parse a line into a ThreadSnapshot object
    // Example: Assuming the line format is "timestamp,threadId,threadName"
    String[] parts = line.split(",");
    if (parts.length == 3) {
        long timestamp = Long.parseLong(parts[0]);
        String threadId = parts[1];
        String threadName = parts[2];
        return new ThreadSnapshot(timestamp, threadId, threadName);
    }
    // Handle invalid line format
    throw new IllegalArgumentException("Invalid line format");
}
